INSERT INTO process_diagrams (diagram_id,site_id,scope_key,stage,period,revision,coverage,mermaid,source_id,boundaries,gaps,updated_on) VALUES ('D012-01','CN0010','jiangbei_existing','historical','2026环评现有工程','1','partial','flowchart TD
A["SMTO结晶洗涤、真空及酸吸收"] --> B["三乙胺回收"]
C["高盐交换及碱洗"] --> D["二效强制循环蒸发结晶"] --> E["冷凝回用喷淋/冷却"]
D --> F["残渣委外"]
G["低盐交换洗涤及设备洗水"] --> H["均质中和/高密沉淀"] --> I["总排水池/博瑞德"]
G --> J["部分直接回用"]
H --> K["污泥压滤干化"] --> L["滤液回流"]
M["瓶洗、地面、实验及初雨"] --> N["除磷沉淀"] --> I',(SELECT source_id FROM wastewater WHERE water_id='W0131' AND site_id='CN0010'),'既有高盐蒸发与低盐分治；膜未识别','分盐水量、TDS、三乙胺、蒸发盐去向、回用水指标及实际能耗','2026-11-27');
